CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key. Stable even when the handle changes, which is why nothing joins on the handle.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The @name. Short, mutable, and reclaimable - so it is an attribute, not an identity.
	"handle" VARCHAR(15) NOT NULL UNIQUE,
	-- Free-text name shown above the handle.
	"display_name" VARCHAR(50) NOT NULL,
	-- Profile text.
	"bio" VARCHAR(160),
	-- Protected accounts hide their tweets from non-followers. Evaluated on read, because a tweet does not carry its own visibility.
	"is_protected" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised inbound follow count. Read on every profile and hovercard.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised outbound follow count. Also the number the fan-out worker uses to decide whether an author is worth pushing.
	"following_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of live tweets of every kind, including retweets.
	"tweet_count" INTEGER NOT NULL DEFAULT 0,
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'An account. Counters are caches of the edge tables; they are read orders of magnitude more often than they change.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key. Stable even when the handle changes, which is why nothing joins on the handle.';
COMMENT ON COLUMN "users"."handle" IS 'The @name. Short, mutable, and reclaimable - so it is an attribute, not an identity.';
COMMENT ON COLUMN "users"."display_name" IS 'Free-text name shown above the handle.';
COMMENT ON COLUMN "users"."bio" IS 'Profile text.';
COMMENT ON COLUMN "users"."is_protected" IS 'Protected accounts hide their tweets from non-followers. Evaluated on read, because a tweet does not carry its own visibility.';
COMMENT ON COLUMN "users"."follower_count" IS 'Denormalised inbound follow count. Read on every profile and hovercard.';
COMMENT ON COLUMN "users"."following_count" IS 'Denormalised outbound follow count. Also the number the fan-out worker uses to decide whether an author is worth pushing.';
COMMENT ON COLUMN "users"."tweet_count" IS 'Denormalised count of live tweets of every kind, including retweets.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "tweets" (
	-- Surrogate primary key. Monotonic, so id ordering is time ordering and paging never needs a timestamp.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that posted. On a retweet this is the retweeter, not the original author.
	"author_id" BIGINT NOT NULL,
	-- tweet | reply | retweet | quote. The discriminator that tells a reader which of the three reference columns is meaningful.
	"kind" VARCHAR(10) NOT NULL DEFAULT 'tweet',
	-- Text content. Null for a pure retweet, which carries no text of its own - that null is the cheapest way to tell a retweet from a quote.
	"body" VARCHAR(280),
	-- Tweet being replied to. Set only when kind is reply.
	"in_reply_to_tweet_id" BIGINT,
	-- Root tweet of the thread, copied down every reply so a whole conversation loads with one indexed read instead of walking the chain.
	"conversation_id" BIGINT,
	-- Tweet being retweeted. Set only when kind is retweet.
	"retweet_of_id" BIGINT,
	-- Tweet being quoted. A quote has its own body, which is why it is not a retweet.
	"quoted_tweet_id" BIGINT,
	-- everyone | following | mentioned. Checked before a reply is accepted, not when the thread is read.
	"reply_permission" VARCHAR(12) NOT NULL DEFAULT 'everyone',
	-- Detected BCP-47 language tag, used for timeline filtering and translation prompts.
	"lang" VARCHAR(8),
	-- Denormalised counter shown on the card.
	"reply_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of rows with retweet_of_id pointing here.
	"retweet_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of quotes, kept apart from retweets because the product shows them separately.
	"quote_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised like total.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Post time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Soft delete. Retweets and replies still point here, so the row has to survive as a tombstone that renders as "unavailable".
	"deleted_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "tweets" IS 'Every kind of post in one table. A reply, a retweet and a quote are all tweets that happen to reference another tweet, so likes, bookmarks, hashtags, timelines and moderation all get to work on one shape instead of four.';
COMMENT ON COLUMN "tweets"."id" IS 'Surrogate primary key. Monotonic, so id ordering is time ordering and paging never needs a timestamp.';
COMMENT ON COLUMN "tweets"."author_id" IS 'Account that posted. On a retweet this is the retweeter, not the original author.';
COMMENT ON COLUMN "tweets"."kind" IS 'tweet | reply | retweet | quote. The discriminator that tells a reader which of the three reference columns is meaningful.';
COMMENT ON COLUMN "tweets"."body" IS 'Text content. Null for a pure retweet, which carries no text of its own - that null is the cheapest way to tell a retweet from a quote.';
COMMENT ON COLUMN "tweets"."in_reply_to_tweet_id" IS 'Tweet being replied to. Set only when kind is reply.';
COMMENT ON COLUMN "tweets"."conversation_id" IS 'Root tweet of the thread, copied down every reply so a whole conversation loads with one indexed read instead of walking the chain.';
COMMENT ON COLUMN "tweets"."retweet_of_id" IS 'Tweet being retweeted. Set only when kind is retweet.';
COMMENT ON COLUMN "tweets"."quoted_tweet_id" IS 'Tweet being quoted. A quote has its own body, which is why it is not a retweet.';
COMMENT ON COLUMN "tweets"."reply_permission" IS 'everyone | following | mentioned. Checked before a reply is accepted, not when the thread is read.';
COMMENT ON COLUMN "tweets"."lang" IS 'Detected BCP-47 language tag, used for timeline filtering and translation prompts.';
COMMENT ON COLUMN "tweets"."reply_count" IS 'Denormalised counter shown on the card.';
COMMENT ON COLUMN "tweets"."retweet_count" IS 'Denormalised count of rows with retweet_of_id pointing here.';
COMMENT ON COLUMN "tweets"."quote_count" IS 'Denormalised count of quotes, kept apart from retweets because the product shows them separately.';
COMMENT ON COLUMN "tweets"."like_count" IS 'Denormalised like total.';
COMMENT ON COLUMN "tweets"."created_at" IS 'Post time.';
COMMENT ON COLUMN "tweets"."deleted_at" IS 'Soft delete. Retweets and replies still point here, so the row has to survive as a tombstone that renders as "unavailable".';

CREATE INDEX "idx_tweets_author_id"
ON "tweets" ("author_id", "id");
CREATE INDEX "idx_tweets_conversation_id"
ON "tweets" ("conversation_id", "id");
CREATE INDEX "idx_tweets_retweet_of"
ON "tweets" ("retweet_of_id");

CREATE TABLE IF NOT EXISTS "follows" (
	-- Account doing the following.
	"follower_id" BIGINT,
	-- Account being followed. Asymmetric by design - the reverse edge is an unrelated row that may never exist.
	"followee_id" BIGINT,
	-- Push every tweet from this account. Stored on the edge because it is a property of the relationship, not of either account.
	"notifications_on" BOOLEAN NOT NULL DEFAULT false,
	-- When the follow started; orders the follower list.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("follower_id", "followee_id")
);

COMMENT ON TABLE "follows" IS 'The graph the timeline is built from. Both directions are indexed: the fan-out worker reads followers of an author, the UI reads who an account follows.';
COMMENT ON COLUMN "follows"."follower_id" IS 'Account doing the following.';
COMMENT ON COLUMN "follows"."followee_id" IS 'Account being followed. Asymmetric by design - the reverse edge is an unrelated row that may never exist.';
COMMENT ON COLUMN "follows"."notifications_on" IS 'Push every tweet from this account. Stored on the edge because it is a property of the relationship, not of either account.';
COMMENT ON COLUMN "follows"."created_at" IS 'When the follow started; orders the follower list.';

CREATE INDEX "idx_follows_followee_created"
ON "follows" ("followee_id", "created_at");

CREATE TABLE IF NOT EXISTS "home_timeline_entries" (
	-- Owner of the timeline. Every row here belongs to exactly one reader.
	"user_id" BIGINT,
	-- Tweet placed on that timeline.
	"tweet_id" BIGINT,
	-- Original author, copied in so the timeline can be filtered by mute or block without joining back to tweets.
	"author_id" BIGINT NOT NULL,
	-- follow | retweet | recommended. Drives the "X retweeted" header and lets injected recommendations be swept out separately.
	"reason" VARCHAR(12) NOT NULL DEFAULT 'follow',
	-- When the entry was written, which for a retweet differs from the original post time.
	"inserted_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id", "tweet_id")
);

COMMENT ON TABLE "home_timeline_entries" IS 'Materialised timeline, written on publish rather than assembled on read. One insert per follower makes reading the home feed a single range scan - and makes a celebrity tweet an enormous write, which is why very large accounts are merged in at read time instead.';
COMMENT ON COLUMN "home_timeline_entries"."user_id" IS 'Owner of the timeline. Every row here belongs to exactly one reader.';
COMMENT ON COLUMN "home_timeline_entries"."tweet_id" IS 'Tweet placed on that timeline.';
COMMENT ON COLUMN "home_timeline_entries"."author_id" IS 'Original author, copied in so the timeline can be filtered by mute or block without joining back to tweets.';
COMMENT ON COLUMN "home_timeline_entries"."reason" IS 'follow | retweet | recommended. Drives the "X retweeted" header and lets injected recommendations be swept out separately.';
COMMENT ON COLUMN "home_timeline_entries"."inserted_at" IS 'When the entry was written, which for a retweet differs from the original post time.';

CREATE INDEX "idx_home_timeline_user_tweet"
ON "home_timeline_entries" ("user_id", "tweet_id");

CREATE TABLE IF NOT EXISTS "likes" (
	-- Tweet liked.
	"tweet_id" BIGINT,
	-- Account that liked it.
	"user_id" BIGINT,
	-- When the like happened; orders both the liker list and the likes tab.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("tweet_id", "user_id")
);

COMMENT ON TABLE "likes" IS 'The largest table in the schema and the narrowest. No surrogate id: nothing ever references a like, so the pair is the whole identity.';
COMMENT ON COLUMN "likes"."tweet_id" IS 'Tweet liked.';
COMMENT ON COLUMN "likes"."user_id" IS 'Account that liked it.';
COMMENT ON COLUMN "likes"."created_at" IS 'When the like happened; orders both the liker list and the likes tab.';

CREATE INDEX "idx_likes_user_created"
ON "likes" ("user_id", "created_at");

CREATE TABLE IF NOT EXISTS "bookmarks" (
	-- Account that saved the tweet.
	"user_id" BIGINT,
	-- Tweet saved.
	"tweet_id" BIGINT,
	-- Save time; the bookmarks tab sorts by this rather than by tweet age.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id", "tweet_id")
);

COMMENT ON TABLE "bookmarks" IS 'Private saves. Identical in shape to likes but deliberately a separate table, because a bookmark is invisible to the author and must never leak into counters or notifications.';
COMMENT ON COLUMN "bookmarks"."user_id" IS 'Account that saved the tweet.';
COMMENT ON COLUMN "bookmarks"."tweet_id" IS 'Tweet saved.';
COMMENT ON COLUMN "bookmarks"."created_at" IS 'Save time; the bookmarks tab sorts by this rather than by tweet age.';

CREATE INDEX "idx_bookmarks_user_created"
ON "bookmarks" ("user_id", "created_at");

CREATE TABLE IF NOT EXISTS "lists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that curates the list.
	"owner_id" BIGINT NOT NULL,
	-- List name shown in the switcher.
	"name" VARCHAR(25) NOT NULL,
	-- Optional blurb on the list page.
	"description" VARCHAR(100),
	-- Private lists are readable only by the owner, and being added to one is not visible to the member.
	"is_private" BOOLEAN NOT NULL DEFAULT false,
	-- Denormalised member total.
	"member_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised count of accounts following the list.
	"follower_count" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "lists" IS 'A curated timeline that is independent of following. Its timeline is read live from tweets by the members, never fanned out, because lists are read rarely enough for the join to be cheap.';
COMMENT ON COLUMN "lists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "lists"."owner_id" IS 'Account that curates the list.';
COMMENT ON COLUMN "lists"."name" IS 'List name shown in the switcher.';
COMMENT ON COLUMN "lists"."description" IS 'Optional blurb on the list page.';
COMMENT ON COLUMN "lists"."is_private" IS 'Private lists are readable only by the owner, and being added to one is not visible to the member.';
COMMENT ON COLUMN "lists"."member_count" IS 'Denormalised member total.';
COMMENT ON COLUMN "lists"."follower_count" IS 'Denormalised count of accounts following the list.';
COMMENT ON COLUMN "lists"."created_at" IS 'Creation time.';

CREATE INDEX "idx_lists_owner_created"
ON "lists" ("owner_id", "created_at");

CREATE TABLE IF NOT EXISTS "list_members" (
	-- List being curated.
	"list_id" BIGINT,
	-- Account placed on the list. Membership implies nothing about following, which is the reason lists exist.
	"member_id" BIGINT,
	-- When the account was added.
	"added_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("list_id", "member_id")
);

COMMENT ON TABLE "list_members" IS 'Who is on a list. Reading a list timeline is a join from here into tweets on (author_id, id), which is exactly the index the profile page already needs.';
COMMENT ON COLUMN "list_members"."list_id" IS 'List being curated.';
COMMENT ON COLUMN "list_members"."member_id" IS 'Account placed on the list. Membership implies nothing about following, which is the reason lists exist.';
COMMENT ON COLUMN "list_members"."added_at" IS 'When the account was added.';

CREATE TABLE IF NOT EXISTS "list_follows" (
	-- List being followed.
	"list_id" BIGINT,
	-- Account following it.
	"user_id" BIGINT,
	-- When the follow started.
	"followed_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("list_id", "user_id")
);

COMMENT ON TABLE "list_follows" IS 'Subscribing to curation done by someone else. Separate from list_members because being on a list and reading it are unrelated actions.';
COMMENT ON COLUMN "list_follows"."list_id" IS 'List being followed.';
COMMENT ON COLUMN "list_follows"."user_id" IS 'Account following it.';
COMMENT ON COLUMN "list_follows"."followed_at" IS 'When the follow started.';

CREATE TABLE IF NOT EXISTS "hashtags" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Normalised lowercase tag without the #, so #Coffee and #coffee are one row.
	"tag" VARCHAR(140) NOT NULL UNIQUE,
	-- First use, which is what lets a genuinely new tag be scored differently from a dormant one.
	"first_seen_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Lifetime uses. Trends are computed from the recent window in tweet_hashtags, not from this column.
	"usage_count" BIGINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "hashtags" IS 'Extracted tags, deduplicated. Pulling them out of the body is what makes tag search an index lookup instead of a wildcard scan over every tweet ever written.';
COMMENT ON COLUMN "hashtags"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "hashtags"."tag" IS 'Normalised lowercase tag without the #, so #Coffee and #coffee are one row.';
COMMENT ON COLUMN "hashtags"."first_seen_at" IS 'First use, which is what lets a genuinely new tag be scored differently from a dormant one.';
COMMENT ON COLUMN "hashtags"."usage_count" IS 'Lifetime uses. Trends are computed from the recent window in tweet_hashtags, not from this column.';

CREATE TABLE IF NOT EXISTS "tweet_hashtags" (
	-- Tweet containing the tag.
	"tweet_id" BIGINT,
	-- Tag used.
	"hashtag_id" BIGINT,
	-- Copied from the tweet so trending windows can be computed here without joining back to tweets.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("tweet_id", "hashtag_id")
);

COMMENT ON TABLE "tweet_hashtags" IS 'Join between tweets and tags, written once at post time by the parser. The denormalised timestamp is what makes "top tags in the last hour" a single index range scan.';
COMMENT ON COLUMN "tweet_hashtags"."tweet_id" IS 'Tweet containing the tag.';
COMMENT ON COLUMN "tweet_hashtags"."hashtag_id" IS 'Tag used.';
COMMENT ON COLUMN "tweet_hashtags"."created_at" IS 'Copied from the tweet so trending windows can be computed here without joining back to tweets.';

CREATE INDEX "idx_tweet_hashtags_tag_created"
ON "tweet_hashtags" ("hashtag_id", "created_at");

CREATE TABLE IF NOT EXISTS "mentions" (
	-- Tweet containing the mention.
	"tweet_id" BIGINT,
	-- Account mentioned, resolved to an id at post time so a later handle change does not break the link.
	"mentioned_user_id" BIGINT,
	-- Character offset of the @handle in the body, which is how the client renders the link without re-parsing the text.
	"start_offset" SMALLINT NOT NULL,
	PRIMARY KEY("tweet_id", "mentioned_user_id")
);

COMMENT ON TABLE "mentions" IS 'Mentions resolved to accounts. The reverse index is the notifications tab: every tweet that mentioned you, in one range scan and without scanning bodies.';
COMMENT ON COLUMN "mentions"."tweet_id" IS 'Tweet containing the mention.';
COMMENT ON COLUMN "mentions"."mentioned_user_id" IS 'Account mentioned, resolved to an id at post time so a later handle change does not break the link.';
COMMENT ON COLUMN "mentions"."start_offset" IS 'Character offset of the @handle in the body, which is how the client renders the link without re-parsing the text.';

CREATE INDEX "idx_mentions_user_tweet"
ON "mentions" ("mentioned_user_id", "tweet_id");

